const renderBenefitPlan=renderPlan;renderPlan=function(){renderBenefitPlan();renderSkillPlan()};function renderSkillPlan(){const saved=getSavedSkills(),chosen=saved.map(url=>skillItems.find(x=>x.url===url)).filter(Boolean),container=document.querySelector('#skill-plan-list');document.querySelector('#skill-plan-count').textContent=chosen.length;if(!chosen.length){container.innerHTML='<div class="skill-plan-empty">还没有添加 Skill。<a href="#skills">去发现技能 →</a></div>';document.querySelector('#copy-skill-bundle').disabled=true;document.querySelector('#skill-bundle-text').value='';return}document.querySelector('#copy-skill-bundle').disabled=false;container.innerHTML=chosen.map(x=>`<div class="skill-plan-row"><div><strong>${x.name}</strong><small>${x.source} · ${x.tools||skillMeta[x.mark]?.tools||'兼容性见来源'}</small></div><button data-remove-skill="${skillItems.indexOf(x)}">移除</button></div>`).join('');container.querySelectorAll('[data-remove-skill]').forEach(b=>b.onclick=()=>toggleSkill(skillItems[Number(b.dataset.removeSkill)].url));let lines=['请先审阅以下 Skill 的来源、兼容性、许可、依赖和权限，确认适合当前工具后再向我说明安装方案。不要自动执行未经审阅的脚本。',''];chosen.forEach((x,i)=>{lines.push(`${i+1}. ${x.name}`,'用途：'+x.desc,'来源：'+x.url,'适用工具：'+(x.tools||skillMeta[x.mark]?.tools||'请检查上游兼容性'),'安装方式：'+(x.command||'请查阅来源项目的安装说明'),'')});document.querySelector('#skill-bundle-text').value=lines.join('\n')}document.querySelector('#copy-skill-bundle').onclick=async function(){try{await navigator.clipboard.writeText(document.querySelector('#skill-bundle-text').value);this.textContent='已复制清单'}catch{this.textContent='复制失败，请手动复制下方清单'}};renderPlan();
